const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const arcDeTriomphe = ee.Geometry.Point(2.2950, 48.8738); // Lon, Lat
  const versailles = ee.Geometry.Point(2.1204, 48.8048); // Lon, Lat

  const targetDate = '2024-08-06';
  const startDate = '2024-08-06';
  const endDate = '2024-08-07'; // One day to ensure coverage for the target date

  // 2. Data Acquisition & Check
  // We need Land Surface Temperature (LST). Sentinel-3 SLSTR L2 LST is a good option.
  // However, the specified date (August 6, 2024) is in the future.
  // Earth Engine only provides historical data. Therefore, no data can be found for this date.
  console.log(`Searching for LST data for: ${targetDate}`);

  // This check will confirm no images exist for a future date.
  const lstCollection = ee.ImageCollection('NOAA/SLT/SLSTR_L2/LST/V1_0')
    .filterDate(startDate, endDate)
    .filterBounds(arcDeTriomphe.union(versailles));

  if (lstCollection.size().getInfo() === 0) {
    console.log(`No Sentinel-3 LST images found for the specified future date (${targetDate}).`);
    console.log("A future date cannot be processed as Earth Engine only contains historical data.");
    console.log("C1");
    return;
  }

  // --- The following code block would be executed if the date was historical and data was found ---
  // Masking function for Sentinel-3 LST
  function maskS3LST(image) {
    // Quality flags for Sentinel-3 SLSTR L2 LST (Bit 0: Cloud contamination)
    // We want pixels where the cloud contamination bit is NOT set (i.e., clear sky).
    const qualityFlags = image.select('quality_flags');
    const cloudContaminationBit = 1 << 0; // Bit 0

    // Mask out pixels where cloud contamination bit is set
    const mask = qualityFlags.bitwiseAnd(cloudContaminationBit).eq(0);

    // Apply scaling factor and convert to Celsius (LST_NN is in Kelvin * 50)
    // LST_NN = LST_NN * 0.02 - 273.15
    const lstCelsius = image.select('LST_NN').multiply(0.02).subtract(273.15);

    return lstCelsius.updateMask(mask).copyProperties(image, ['system:time_start']);
  }

  const maskedLST = lstCollection.map(maskS3LST);

  // Take the mean LST over the collection if multiple images exist
  const compositeLST = maskedLST.mean();

  if (compositeLST.bandNames().size().getInfo() === 0) {
      console.log("No valid LST data after cloud masking for the region.");
      console.log("C2");
      return;
  }

  // Define reduction parameters
  const reducer = ee.Reducer.mean();
  const scale = 1000; // Sentinel-3 LST resolution is 1km

  // Calculate LST for Arc de Triomphe
  const arcLST = compositeLST.reduceRegion({
    reducer: reducer,
    geometry: arcDeTriomphe,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_NN');

  // Calculate LST for Versailles
  const versaillesLST = compositeLST.reduceRegion({
    reducer: reducer,
    geometry: versailles,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_NN');

  // Get values
  const arcLSTValue = await arcLST.getInfo();
  const versaillesLSTValue = await versaillesLST.getInfo();

  // 3. Validation & Final Answer
  if (arcLSTValue === null || versaillesLSTValue === null) {
    console.log("C3"); // Calculation failure, possibly due to no valid pixels at reduction point
    return;
  }

  const difference = arcLSTValue - versaillesLSTValue;

  console.log(`LST Arc de Triomphe: ${arcLSTValue.toFixed(2)} °C`);
  console.log(`LST Versailles: ${versaillesLSTValue.toFixed(2)} °C`);
  console.log(`Difference (Arc - Versailles): ${difference.toFixed(2)} °C`);

  if (difference >= 5) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
